from __future__ import annotations


class MicroDBError(Exception):
    """Base exception for all microdb errors."""


class LexError(MicroDBError):
    """Raised when lexical analysis encounters an invalid character or token."""

    def __init__(self, message: str = "Lexical error", offset: int = 0) -> None:
        super().__init__(message)
        self.offset: int = offset


class ParseError(MicroDBError):
    """Raised when parsing encounters invalid syntax."""

    def __init__(self, message: str = "Parse error", offset: int = 0) -> None:
        super().__init__(message)
        self.offset: int = offset


class SchemaError(MicroDBError):
    """Raised when a table schema or row data is invalid."""


class TypeMismatchError(MicroDBError):
    """Raised when an operation is applied to incompatible types."""


class UnknownColumnError(MicroDBError):
    """Raised when a referenced column does not exist."""


class AmbiguousColumnError(MicroDBError):
    """Raised when an unqualified column name matches multiple tables."""


class UnknownTableError(MicroDBError):
    """Raised when a referenced table does not exist."""


class UnknownFunctionError(MicroDBError):
    """Raised when a referenced function does not exist."""


class ArityError(MicroDBError):
    """Raised when a function is called with the wrong number of arguments."""


class AggregateError(MicroDBError):
    """Raised when an aggregate function is misused."""


class GroupingError(MicroDBError):
    """Raised when a non-grouped, non-aggregated expression is selected with GROUP BY."""

from __future__ import annotations

from microdb.errors import TypeMismatchError

VALID_TYPES: frozenset[str] = frozenset({"INT", "FLOAT", "TEXT", "BOOL"})


def type_of(v: object) -> str:
    if v is None:
        return "NULL"
    if isinstance(v, bool):
        return "BOOL"
    if isinstance(v, int):
        return "INT"
    if isinstance(v, float):
        return "FLOAT"
    if isinstance(v, str):
        return "TEXT"
    raise TypeMismatchError(f"Unsupported value: {v!r}")


def is_numeric(v: object) -> bool:
    return not isinstance(v, bool) and isinstance(v, (int, float))


def _ensure_logical(v: object) -> bool | None:
    if v is not None and not isinstance(v, bool):
        raise TypeMismatchError(f"Expected BOOL or NULL, got {type_of(v)}")
    return v


def and_(a: bool | None, b: bool | None) -> bool | None:
    la = _ensure_logical(a)
    lb = _ensure_logical(b)
    if la is False or lb is False:
        return False
    if la is True and lb is True:
        return True
    return None


def or_(a: bool | None, b: bool | None) -> bool | None:
    la = _ensure_logical(a)
    lb = _ensure_logical(b)
    if la is True or lb is True:
        return True
    if la is False and lb is False:
        return False
    return None


def not_(a: bool | None) -> bool | None:
    la = _ensure_logical(a)
    if la is None:
        return None
    return not la


def compare_eq(a: object, b: object) -> bool | None:
    if a is None or b is None:
        return None
    if is_numeric(a) and is_numeric(b):
        return bool(a == b)
    if isinstance(a, str) and isinstance(b, str):
        return a == b
    if isinstance(a, bool) and isinstance(b, bool):
        return a == b
    raise TypeMismatchError(f"Cannot compare {type_of(a)} and {type_of(b)}")


def compare_lt(a: object, b: object) -> bool | None:
    if a is None or b is None:
        return None
    if is_numeric(a) and is_numeric(b):
        return bool(a < b)  # type: ignore[operator]
    if isinstance(a, str) and isinstance(b, str):
        return a < b
    if isinstance(a, bool) and isinstance(b, bool):
        return (not a) and b
    raise TypeMismatchError(f"Cannot order {type_of(a)} and {type_of(b)}")


def compare(op: str, a: object, b: object) -> bool | None:
    if op == "=":
        return compare_eq(a, b)
    if op == "<>":
        return not_(compare_eq(a, b))
    if op == "<":
        return compare_lt(a, b)
    if op == ">":
        return compare_lt(b, a)
    if op == "<=":
        lt = compare_lt(a, b)
        eq = compare_eq(a, b)
        return None if (lt is None or eq is None) else (lt or eq)
    if op == ">=":
        gt = compare_lt(b, a)
        eq = compare_eq(a, b)
        return None if (gt is None or eq is None) else (gt or eq)
    raise ValueError(f"Unknown comparison operator: {op}")


def arith(op: str, a: object, b: object) -> object:
    if op not in {"+", "-", "*", "/", "%"}:
        raise ValueError(f"Unknown arithmetic operator: {op}")
    if (a is not None and not is_numeric(a)) or (b is not None and not is_numeric(b)):
        raise TypeMismatchError(f"Arithmetic {op!r} requires numeric operands")
    if op == "%":
        if (a is not None and type_of(a) != "INT") or (b is not None and type_of(b) != "INT"):
            raise TypeMismatchError("Modulo '%' requires INT operands")
    if a is None or b is None:
        return None
    assert isinstance(a, (int, float)) and isinstance(b, (int, float))
    if op == "+":
        return a + b
    if op == "-":
        return a - b
    if op == "*":
        return a * b
    if op == "/":
        return None if b == 0 else float(a) / float(b)
    return None if b == 0 else int(a) % int(b)


def negate(a: object) -> object:
    if a is None:
        return None
    if not is_numeric(a):
        raise TypeMismatchError(f"Unary minus requires numeric operand, got {type_of(a)}")
    assert isinstance(a, (int, float))
    return -a

from __future__ import annotations

import dataclasses

from microdb.errors import SchemaError
from microdb.value import VALID_TYPES, type_of


@dataclasses.dataclass(frozen=True)
class Column:
    name: str
    type: str


def _validate_cell(value: object, col_type: str, col_name: str) -> object:
    if value is None:
        return None
    val_type = type_of(value)
    if col_type == "FLOAT" and val_type == "INT":
        assert isinstance(value, int)
        return float(value)
    if val_type != col_type:
        raise SchemaError(
            f"Column {col_name!r} expects {col_type}, got {val_type} ({value!r})"
        )
    return value


class Table:
    def __init__(
        self, name: str, columns: list[Column], rows: list[list[object]]
    ) -> None:
        if not columns:
            raise SchemaError("Table must have at least one column")
        seen_names: set[str] = set()
        col_index_map: dict[str, int] = {}
        for idx, col in enumerate(columns):
            if col.type not in VALID_TYPES:
                raise SchemaError(f"Invalid column type {col.type!r} for {col.name!r}")
            if col.name in seen_names:
                raise SchemaError(f"Duplicate column name: {col.name!r}")
            seen_names.add(col.name)
            col_index_map[col.name] = idx

        validated_rows: list[list[object]] = []
        num_cols = len(columns)
        for row in rows:
            if len(row) != num_cols:
                raise SchemaError(
                    f"Row length {len(row)} does not match column count {num_cols}"
                )
            new_row = [
                _validate_cell(cell, columns[i].type, columns[i].name)
                for i, cell in enumerate(row)
            ]
            validated_rows.append(new_row)

        self._name: str = name
        self._columns: list[Column] = list(columns)
        self._rows: list[list[object]] = validated_rows
        self._col_index: dict[str, int] = col_index_map

    @property
    def name(self) -> str:
        return self._name

    @property
    def columns(self) -> list[Column]:
        return self._columns

    @property
    def rows(self) -> list[list[object]]:
        return self._rows

    def column_index(self, name: str) -> int:
        if name not in self._col_index:
            raise SchemaError(f"Unknown column {name!r} in table {self._name!r}")
        return self._col_index[name]

