from __future__ import annotations

from collections.abc import Sequence

from microdb.errors import ArityError, TypeMismatchError, UnknownFunctionError
from microdb.value import compare_lt, is_numeric, type_of

AGGREGATES: frozenset[str] = frozenset({"count", "sum", "avg", "min", "max"})


def validate_aggregate_call(name: str, arity: int, is_star: bool) -> None:
    lower = name.lower()
    if lower not in AGGREGATES:
        raise UnknownFunctionError(f"Unknown aggregate function {name!r}")
    if not is_star and arity != 1:
        raise ArityError(f"{lower} expects 1 argument, got {arity}")


def compute_aggregate(
    name: str,
    values: Sequence[object],
    is_star: bool = False,
    row_count: int | None = None,
) -> object:
    lower = name.lower()
    if lower == "count":
        if is_star:
            return row_count if row_count is not None else len(values)
        return sum(1 for v in values if v is not None)

    non_null = [v for v in values if v is not None]
    if lower in ("sum", "avg"):
        for v in non_null:
            if not is_numeric(v):
                raise TypeMismatchError(f"{lower} requires numeric input, got {type_of(v)}")
        if not non_null:
            return None
        total = sum(non_null)  # type: ignore[arg-type]
        if lower == "avg":
            return float(total) / float(len(non_null))
        if any(isinstance(v, float) for v in non_null):
            return float(total)
        return int(total)

    if lower in ("min", "max"):
        if not non_null:
            return None
        best = non_null[0]
        compare_lt(best, best)
        for v in non_null[1:]:
            if lower == "min":
                if compare_lt(v, best) is True:
                    best = v
            else:
                if compare_lt(best, v) is True:
                    best = v
        return best

    raise UnknownFunctionError(f"Unknown aggregate function {name!r}")

from __future__ import annotations

from collections.abc import Callable, Sequence
import dataclasses

from microdb.aggregate import validate_aggregate_call
from microdb.errors import (
    AggregateError,
    AmbiguousColumnError,
    ArityError,
    TypeMismatchError,
    UnknownColumnError,
    UnknownFunctionError,
    UnknownTableError,
)
from microdb.parser import (
     COMPARE_OPS,
    AggregateCall,
    BinaryExpr,
    ColumnRef,
    Expr,
    FuncCall,
    IsNullExpr,
    LiteralExpr,
    UnaryExpr,
)
from microdb.value import and_, arith, compare, is_numeric, negate, not_, or_, type_of

SCALAR_FUNCTIONS: frozenset[str] = frozenset(
    {"concat", "upper", "lower", "length", "abs", "coalesce"}
)


@dataclasses.dataclass(frozen=True)
class SourceColumn:
    table: str | None
    name: str
    col_type: str


class RowSchema:
    def __init__(
        self, columns: Sequence[SourceColumn], valid_tables: frozenset[str]
    ) -> None:
        self.columns: tuple[SourceColumn, ...] = tuple(columns)
        self.valid_tables: frozenset[str] = valid_tables

    def resolve(self, table: str | None, name: str) -> int:
        if table is not None:
            if table not in self.valid_tables:
                raise UnknownTableError(f"Unknown table {table!r}")
            matches = [
                i
                for i, c in enumerate(self.columns)
                if c.table == table and c.name == name
            ]
            if not matches:
                raise UnknownColumnError(f"Unknown column '{table}.{name}'")
            if len(matches) > 1:
                raise AmbiguousColumnError(f"Ambiguous column '{table}.{name}'")
            return matches[0]
        matches = [i for i, c in enumerate(self.columns) if c.name == name]
        if not matches:
            raise UnknownColumnError(f"Unknown column {name!r}")
        if len(matches) > 1:
            raise AmbiguousColumnError(f"Ambiguous column {name!r}")
        return matches[0]


def validate_scalar_call(name: str, arity: int) -> None:
    lower = name.lower()
    if lower not in SCALAR_FUNCTIONS:
        raise UnknownFunctionError(f"Unknown function {name!r}")
    if lower == "concat" and arity < 2:
        raise ArityError(f"concat expects at least 2 arguments, got {arity}")
    if lower == "coalesce" and arity < 1:
        raise ArityError(f"coalesce expects at least 1 argument, got {arity}")
    if lower in ("upper", "lower", "length", "abs") and arity != 1:
        raise ArityError(f"{lower} expects 1 argument, got {arity}")


def eval_scalar_function(name: str, args: Sequence[object]) -> object:
    lower = name.lower()
    validate_scalar_call(lower, len(args))
    if lower == "concat":
        for arg in args:
            if arg is not None and not isinstance(arg, str):
                raise TypeMismatchError(f"concat expects TEXT, got {type_of(arg)}")
        if any(arg is None for arg in args):
            return None
        return "".join(str(a) for a in args)
    if lower == "coalesce":
        for arg in args:
            if arg is not None:
                return arg
        return None
    arg0 = args[0]
    if arg0 is None:
        return None
    if lower in ("upper", "lower", "length"):
        if not isinstance(arg0, str):
            raise TypeMismatchError(f"{lower} expects TEXT, got {type_of(arg0)}")
        if lower == "upper":
            return arg0.upper()
        if lower == "lower":
            return arg0.lower()
        return len(arg0)
    if not is_numeric(arg0):
        raise TypeMismatchError(f"abs expects numeric, got {type_of(arg0)}")
    assert isinstance(arg0, (int, float))
    return abs(arg0)


def validate_expr_functions(expr: Expr) -> None:
    if isinstance(expr, FuncCall):
        validate_scalar_call(expr.name, len(expr.args))
        for arg in expr.args:
            validate_expr_functions(arg)
    elif isinstance(expr, AggregateCall):
        validate_aggregate_call(expr.name, len(expr.args), expr.is_star)
        for arg in expr.args:
            validate_expr_functions(arg)
    elif isinstance(expr, UnaryExpr):
        validate_expr_functions(expr.operand)
    elif isinstance(expr, BinaryExpr):
        validate_expr_functions(expr.left)
        validate_expr_functions(expr.right)
    elif isinstance(expr, IsNullExpr):
        validate_expr_functions(expr.operand)


def eval_expr(
    expr: Expr,
    schema: RowSchema,
    row: Sequence[object],
    col_resolver: Callable[[ColumnRef], object] | None = None,
) -> object:
    if isinstance(expr, LiteralExpr):
        return expr.value
    if isinstance(expr, ColumnRef):
        if col_resolver is not None:
            return col_resolver(expr)
        idx = schema.resolve(expr.table, expr.name)
        return row[idx]
    if isinstance(expr, AggregateCall):
        raise AggregateError(f"Aggregate {expr.name!r} is not allowed in this clause")
    if isinstance(expr, UnaryExpr):
        val = eval_expr(expr.operand, schema, row, col_resolver)
        return not_(val) if expr.op == "NOT" else negate(val)  # type: ignore[arg-type]
    if isinstance(expr, IsNullExpr):
        val = eval_expr(expr.operand, schema, row, col_resolver)
        return (val is not None) if expr.negated else (val is None)
    if isinstance(expr, BinaryExpr):
        return _eval_binary(expr, schema, row, col_resolver)
    if isinstance(expr, FuncCall):
        validate_scalar_call(expr.name, len(expr.args))
        vals = [eval_expr(a, schema, row, col_resolver) for a in expr.args]
        return eval_scalar_function(expr.name, vals)
    raise TypeError(f"Unsupported expression node: {expr!r}")


def _eval_binary(
    expr: BinaryExpr,
    schema: RowSchema,
    row: Sequence[object],
    col_resolver: Callable[[ColumnRef], object] | None,
) -> object:
    left = eval_expr(expr.left, schema, row, col_resolver)
    right = eval_expr(expr.right, schema, row, col_resolver)
    if expr.op == "AND":
        return and_(left, right)  # type: ignore[arg-type]
    if expr.op == "OR":
        return or_(left, right)  # type: ignore[arg-type]
    if expr.op in COMPARE_OPS:
        return compare(expr.op, left, right)
    return arith(expr.op, left, right)


def eval_predicate(
    expr: Expr,
    schema: RowSchema,
    row: Sequence[object],
    col_resolver: Callable[[ColumnRef], object] | None = None,
) -> bool:
    val = eval_expr(expr, schema, row, col_resolver)
    if val is not None and not isinstance(val, bool):
        raise TypeMismatchError(f"Predicate must evaluate to BOOL, got {type_of(val)}")
    return val is True

from __future__ import annotations

from collections.abc import Iterator, Sequence
import dataclasses

from microdb.errors import AggregateError
from microdb.expr import validate_expr_functions
from microdb.parser import (
    AggregateCall,
    BinaryExpr,
    Expr,
    ExprSelectItem,
    FuncCall,
    IsNullExpr,
    JoinClause,
    OrderItem,
    Query,
    SelectItem,
    UnaryExpr,
    contains_aggregate,
)


@dataclasses.dataclass(frozen=True)
class Stage:
    name: str


@dataclasses.dataclass(frozen=True)
class FromJoinStage(Stage):
    from_table: str
    join: JoinClause | None


@dataclasses.dataclass(frozen=True)
class WhereStage(Stage):
    predicate: Expr


@dataclasses.dataclass(frozen=True)
class GroupStage(Stage):
    keys: tuple[Expr, ...]


@dataclasses.dataclass(frozen=True)
class AggregateStage(Stage):
    aggregates: tuple[AggregateCall, ...]


@dataclasses.dataclass(frozen=True)
class HavingStage(Stage):
    predicate: Expr


@dataclasses.dataclass(frozen=True)
class SelectStage(Stage):
    items: tuple[SelectItem, ...]


@dataclasses.dataclass(frozen=True)
class DistinctStage(Stage):
    pass


@dataclasses.dataclass(frozen=True)
class OrderStage(Stage):
    items: tuple[OrderItem, ...]


@dataclasses.dataclass(frozen=True)
class SliceStage(Stage):
    offset: int | None
    limit: int | None


class Plan(Sequence[Stage]):
    def __init__(
        self, query: Query, stages: Sequence[Stage], is_grouped: bool
    ) -> None:
        self.query: Query = query
        self.stages: tuple[Stage, ...] = tuple(stages)
        self.is_grouped: bool = is_grouped

    def __getitem__(self, index: int | slice) -> Stage | Sequence[Stage]:  # type: ignore[override]
        return self.stages[index]

    def __len__(self) -> int:
        return len(self.stages)

    def __iter__(self) -> Iterator[Stage]:
        return iter(self.stages)

    def __repr__(self) -> str:
        return f"Plan({list(self.stages)!r})"


def _collect_aggregates(expr: Expr, out: list[AggregateCall]) -> None:
    if isinstance(expr, AggregateCall):
        out.append(expr)
    elif isinstance(expr, UnaryExpr):
        _collect_aggregates(expr.operand, out)
    elif isinstance(expr, BinaryExpr):
        _collect_aggregates(expr.left, out)
        _collect_aggregates(expr.right, out)
    elif isinstance(expr, IsNullExpr):
        _collect_aggregates(expr.operand, out)
    elif isinstance(expr, FuncCall):
        for arg in expr.args:
            _collect_aggregates(arg, out)


def _validate_query(query: Query) -> list[AggregateCall]:
    if query.join is not None:
        if contains_aggregate(query.join.on):
            raise AggregateError("Aggregate functions are not allowed in JOIN ON")
        validate_expr_functions(query.join.on)
    if query.where is not None:
        if contains_aggregate(query.where):
            raise AggregateError("Aggregate functions are not allowed in WHERE")
        validate_expr_functions(query.where)
    for g in query.group_by:
        if contains_aggregate(g):
            raise AggregateError("Aggregate functions are not allowed in GROUP BY")
        validate_expr_functions(g)
    aggs: list[AggregateCall] = []
    if query.having is not None:
        validate_expr_functions(query.having)
        _collect_aggregates(query.having, aggs)
    for item in query.select_items:
        if isinstance(item, ExprSelectItem):
            validate_expr_functions(item.expr)
            _collect_aggregates(item.expr, aggs)
    for order_item in query.order_by:
        validate_expr_functions(order_item.expr)
        _collect_aggregates(order_item.expr, aggs)
    return aggs


def plan(query: Query) -> Plan:
    aggs = _validate_query(query)
    is_grouped = bool(query.group_by) or (query.having is not None) or bool(aggs)
    stages: list[Stage] = [
        FromJoinStage(name="FROM", from_table=query.from_table, join=query.join)
    ]
    if query.where is not None:
        stages.append(WhereStage(name="WHERE", predicate=query.where))
    if query.group_by:
        stages.append(GroupStage(name="GROUP_BY", keys=query.group_by))
    if is_grouped:
        stages.append(AggregateStage(name="AGGREGATE", aggregates=tuple(aggs)))
    if query.having is not None:
        stages.append(HavingStage(name="HAVING", predicate=query.having))
    stages.append(SelectStage(name="SELECT", items=query.select_items))
    if query.distinct:
        stages.append(DistinctStage(name="DISTINCT"))
    if query.order_by:
        stages.append(OrderStage(name="ORDER_BY", items=query.order_by))
    if query.offset is not None or query.limit is not None:
        stages.append(SliceStage(name="SLICE", offset=query.offset, limit=query.limit))
    return Plan(query=query, stages=stages, is_grouped=is_grouped)

from __future__ import annotations

from collections.abc import Sequence
import dataclasses
import functools

from microdb.aggregate import compute_aggregate, validate_aggregate_call
from microdb.errors import (
    AmbiguousColumnError,
    GroupingError,
    TypeMismatchError,
    UnknownColumnError,
    UnknownTableError,
)
from microdb.expr import (
    RowSchema,
    SourceColumn,
    eval_expr,
    eval_predicate,
    eval_scalar_function,
    validate_scalar_call,
)
from microdb.parser import (
     COMPARE_OPS,
    AggregateCall,
    BinaryExpr,
    ColumnRef,
    Expr,
    ExprSelectItem,
    FuncCall,
    IsNullExpr,
    JoinClause,
    LiteralExpr,
    OrderItem,
    Query,
    SelectItem,
    StarSelectItem,
    UnaryExpr,
    parse,
)
from microdb.planner import Plan, plan
from microdb.schema import Table
from microdb.value import (
    and_,
    arith,
    compare,
    compare_eq,
    compare_lt,
    negate,
    not_,
    or_,
    type_of,
)


@dataclasses.dataclass(frozen=True)
class Result:
    columns: list[str]
    rows: list[list[object]]


@dataclasses.dataclass(frozen=True)
class _ProjectedCol:
    output_name: str
    expr: Expr
    alias: str | None


def _key_part(val: object) -> tuple[str, object]:
    if val is None:
        return ("NULL", None)
    if isinstance(val, bool):
        return ("BOOL", val)
    if isinstance(val, (int, float)):
        return ("NUM", val)
    return ("TEXT", val)


def _row_key(values: Sequence[object]) -> tuple[tuple[str, object], ...]:
    return tuple(_key_part(v) for v in values)


def _expr_matches(e1: Expr, e2: Expr, schema: RowSchema) -> bool:
    if isinstance(e1, LiteralExpr) and isinstance(e2, LiteralExpr):
        return type_of(e1.value) == type_of(e2.value) and e1.value == e2.value
    if isinstance(e1, ColumnRef) and isinstance(e2, ColumnRef):
        return schema.resolve(e1.table, e1.name) == schema.resolve(e2.table, e2.name)
    if isinstance(e1, UnaryExpr) and isinstance(e2, UnaryExpr):
        return e1.op == e2.op and _expr_matches(e1.operand, e2.operand, schema)
    if isinstance(e1, BinaryExpr) and isinstance(e2, BinaryExpr):
        return (
            e1.op == e2.op
            and _expr_matches(e1.left, e2.left, schema)
            and _expr_matches(e1.right, e2.right, schema)
        )
    if isinstance(e1, IsNullExpr) and isinstance(e2, IsNullExpr):
        return e1.negated == e2.negated and _expr_matches(e1.operand, e2.operand, schema)
    if isinstance(e1, FuncCall) and isinstance(e2, FuncCall):
        return (
            e1.name.lower() == e2.name.lower()
            and len(e1.args) == len(e2.args)
            and all(_expr_matches(a, b, schema) for a, b in zip(e1.args, e2.args))
        )
    if isinstance(e1, AggregateCall) and isinstance(e2, AggregateCall):
        return (
            e1.name.lower() == e2.name.lower()
            and e1.is_star == e2.is_star
            and len(e1.args) == len(e2.args)
            and all(_expr_matches(a, b, schema) for a, b in zip(e1.args, e2.args))
        )
    return False


def _validate_row_expr(expr: Expr, schema: RowSchema) -> None:
    if isinstance(expr, ColumnRef):
        schema.resolve(expr.table, expr.name)
    elif isinstance(expr, UnaryExpr):
        _validate_row_expr(expr.operand, schema)
    elif isinstance(expr, BinaryExpr):
        _validate_row_expr(expr.left, schema)
        _validate_row_expr(expr.right, schema)
    elif isinstance(expr, IsNullExpr):
        _validate_row_expr(expr.operand, schema)
    elif isinstance(expr, FuncCall):
        for arg in expr.args:
            _validate_row_expr(arg, schema)


def _validate_group_expr(
    expr: Expr,
    group_by: Sequence[Expr],
    schema: RowSchema,
    aliases: frozenset[str] = frozenset(),
) -> None:
    for g in group_by:
        if _expr_matches(expr, g, schema):
            return
    if isinstance(expr, AggregateCall):
        validate_aggregate_call(expr.name, len(expr.args), expr.is_star)
        for arg in expr.args:
            _validate_row_expr(arg, schema)
        return
    if isinstance(expr, LiteralExpr):
        return
    if isinstance(expr, ColumnRef):
        if expr.table is None and expr.name in aliases:
            return
        schema.resolve(expr.table, expr.name)
        raise GroupingError(
            f"Column {expr.source_text!r} must appear in GROUP BY or be aggregated"
        )
    if isinstance(expr, UnaryExpr):
        _validate_group_expr(expr.operand, group_by, schema, aliases)
    elif isinstance(expr, BinaryExpr):
        _validate_group_expr(expr.left, group_by, schema, aliases)
        _validate_group_expr(expr.right, group_by, schema, aliases)
    elif isinstance(expr, IsNullExpr):
        _validate_group_expr(expr.operand, group_by, schema, aliases)
    elif isinstance(expr, FuncCall):
        for arg in expr.args:
            _validate_group_expr(arg, group_by, schema, aliases)


def _exec_from_join(
    from_name: str, join: JoinClause | None, tables: dict[str, Table]
) -> tuple[RowSchema, list[list[object]]]:
    if from_name not in tables:
        raise UnknownTableError(f"Unknown table {from_name!r}")
    left_tbl = tables[from_name]
    left_cols = [SourceColumn(from_name, c.name, c.type) for c in left_tbl.columns]
    if join is None:
        schema = RowSchema(left_cols, frozenset({from_name}))
        return schema, [list(r) for r in left_tbl.rows]

    if join.table not in tables:
        raise UnknownTableError(f"Unknown table {join.table!r}")
    right_tbl = tables[join.table]
    right_cols = [SourceColumn(join.table, c.name, c.type) for c in right_tbl.columns]
    schema = RowSchema(left_cols + right_cols, frozenset({from_name, join.table}))
    _validate_row_expr(join.on, schema)

    rows: list[list[object]] = []
    null_right: list[object] = [None] * len(right_tbl.columns)
    for l_row in left_tbl.rows:
        matched = False
        for r_row in right_tbl.rows:
            combined = list(l_row) + list(r_row)
            if eval_predicate(join.on, schema, combined):
                rows.append(combined)
                matched = True
        if join.join_type == "LEFT" and not matched:
            rows.append(list(l_row) + list(null_right))
    return schema, rows


def _expand_select_items(
    items: Sequence[SelectItem], schema: RowSchema
) -> list[_ProjectedCol]:
    expanded: list[_ProjectedCol] = []
    for item in items:
        if isinstance(item, StarSelectItem):
            if item.table is not None and item.table not in schema.valid_tables:
                raise UnknownTableError(f"Unknown table {item.table!r}")
            for col in schema.columns:
                if item.table is None or col.table == item.table:
                    ref = ColumnRef(table=col.table, name=col.name, source_text=col.name, bare=True)
                    expanded.append(_ProjectedCol(col.name, ref, None))
        else:
            expr = item.expr
            if item.alias is not None:
                out_name = item.alias
            elif isinstance(expr, ColumnRef) and expr.bare:
                out_name = expr.name
            else:
                out_name = expr.source_text
            expanded.append(_ProjectedCol(out_name, expr, item.alias))
    return expanded


def _eval_group_expr(
    expr: Expr,
    group_by: Sequence[Expr],
    group_keys: Sequence[object],
    group_rows: Sequence[Sequence[object]],
    schema: RowSchema,
    alias_lookup: dict[str, object] | None = None,
) -> object:
    if isinstance(expr, ColumnRef) and expr.table is None and alias_lookup is not None:
        if expr.name in alias_lookup:
            return alias_lookup[expr.name]
    for idx, g_expr in enumerate(group_by):
        if _expr_matches(expr, g_expr, schema):
            return group_keys[idx]
    if isinstance(expr, AggregateCall):
        if expr.is_star:
            return compute_aggregate(expr.name, (), is_star=True, row_count=len(group_rows))
        vals = [eval_expr(expr.args[0], schema, r) for r in group_rows]
        return compute_aggregate(expr.name, vals, is_star=False, row_count=len(group_rows))
    if isinstance(expr, LiteralExpr):
        return expr.value
    if isinstance(expr, ColumnRef):
        schema.resolve(expr.table, expr.name)
        raise GroupingError(
            f"Column {expr.source_text!r} must appear in GROUP BY or be aggregated"
        )
    if isinstance(expr, UnaryExpr):
        val = _eval_group_expr(expr.operand, group_by, group_keys, group_rows, schema, alias_lookup)
        return not_(val) if expr.op == "NOT" else negate(val)  # type: ignore[arg-type]
    if isinstance(expr, IsNullExpr):
        val = _eval_group_expr(expr.operand, group_by, group_keys, group_rows, schema, alias_lookup)
        return (val is not None) if expr.negated else (val is None)
    if isinstance(expr, BinaryExpr):
        left = _eval_group_expr(expr.left, group_by, group_keys, group_rows, schema, alias_lookup)
        right = _eval_group_expr(expr.right, group_by, group_keys, group_rows, schema, alias_lookup)
        if expr.op == "AND":
            return and_(left, right)  # type: ignore[arg-type]
        if expr.op == "OR":
            return or_(left, right)  # type: ignore[arg-type]
        if expr.op in COMPARE_OPS:
            return compare(expr.op, left, right)
        return arith(expr.op, left, right)
    if isinstance(expr, FuncCall):
        validate_scalar_call(expr.name, len(expr.args))
        args = [
            _eval_group_expr(a, group_by, group_keys, group_rows, schema, alias_lookup)
            for a in expr.args
        ]
        return eval_scalar_function(expr.name, args)
    raise TypeError(f"Unsupported expression: {expr!r}")


def _form_groups(
    rows: Sequence[list[object]], group_by: Sequence[Expr], schema: RowSchema
) -> list[tuple[tuple[object, ...], list[list[object]]]]:
    for g in group_by:
        _validate_row_expr(g, schema)
    if not group_by:
        return [((), list(rows))]
    groups_map: dict[tuple[tuple[str, object], ...], tuple[tuple[object, ...], list[list[object]]]] = {}
    for row in rows:
        raw_vals = tuple(eval_expr(g, schema, row) for g in group_by)
        k = _row_key(raw_vals)
        if k not in groups_map:
            groups_map[k] = (raw_vals, [row])
        else:
            groups_map[k][1].append(row)
    return list(groups_map.values())


def _resolve_alias_index(name: str, projected: Sequence[_ProjectedCol]) -> int | None:
    matches = [i for i, p in enumerate(projected) if p.alias == name]
    if len(matches) > 1:
        raise AmbiguousColumnError(f"Ambiguous alias {name!r}")
    return matches[0] if matches else None


def _resolve_distinct_col(
    ref: ColumnRef, projected: Sequence[_ProjectedCol], schema: RowSchema
) -> int:
    if ref.table is None:
        alias_idx = _resolve_alias_index(ref.name, projected)
        if alias_idx is not None:
            return alias_idx
        matches = [i for i, p in enumerate(projected) if p.output_name == ref.name]
        if len(matches) == 1:
            return matches[0]
        if len(matches) > 1:
            raise AmbiguousColumnError(f"Ambiguous output column {ref.name!r}")
